// GearSwap Atelier · job_access.js: the sets a job can use with the subjob shown.
// A set written for an ability or a spell (sets.precast.JA.Jump, sets.midcast.Utsusemi, sets.buff["Saber Dance"]) is
// of use only when the main job has it, or the subjob at its level: the list of sets leaves the others out, with a
// line that counts them and shows them again on a click. The tables come from job_access_data.js (generated by
// scripts/atelier/build_job_access.py from the job ability databases and the game's spells).
//
// What cannot be told stays shown: a set whose name is the player's own (sets.midcast.PhalanxPotency), an ability
// of a job without a database, the weaponskill sets (what a job can use depends on the weapon in hand).

Object.assign(T.fr, {accHidden: '{n} set(s) masqué(s) : pas pour {j}', accShow: 'Les montrer', accHide: 'Les masquer',
  accTip: 'Des sets écrits pour une ability ou un sort que ni {m} ni le sub {s} n’ont (un autre sub les utilise). Ils restent dans ton fichier.'});
Object.assign(T.en, {accHidden: '{n} set(s) hidden: not for {j}', accShow: 'Show them', accHide: 'Hide them',
  accTip: 'Sets written for an ability or a spell that neither {m} nor the subjob {s} has (another subjob uses them). They stay in your file.'});

// The kinds of abilities a set can be written for as a whole (sets.precast.Waltz, sets.precast.Step...): the
// abilities whose name says the kind
const ACCESS_KINDS = {Waltz: /Waltz/, Step: /[Ss]tep$/, Samba: /Samba/, Jig: /Jig$/, Flourish1: /Flourish/, Flourish2: /Flourish/, Flourish3: /Flourish/};
// Segments of a path that name no ability or spell
const ACCESS_PLAIN = new Set(['sets', 'precast', 'midcast', 'buff', 'JA', 'FC', 'WS', 'RA', 'Pet', 'engaged', 'idle']);
// A set's last word is often how it is worn, not what it is for
const ACCESS_MODES = /^(MagicBurst|Acc|acc|PDT|MDT|Group|Solo|Trust|Normal|SIRD|Potency|Self|Other|Clim)$/;
// The jobs that have a pet as a main job, and as a subjob (a /DRG has no wyvern, a /PUP no automaton)
const PET_MAIN = ['BST', 'SMN', 'DRG', 'PUP', 'GEO'], PET_SUB = ['BST', 'SMN'];

// main job at `main`, subjob at `sub`: can an ability's rows ([[JOB, level, main only]]) be used?
function accessJa(rows, job, sub, lv){
  return rows.some(([j, level, mainOnly]) => (j === job && level <= lv.main) || (!mainOnly && j === sub && level <= lv.sub));
}
// the same for a spell's levels ({JOB: level}); a level over 99 is a main job's gift
function accessSpell(levels, job, sub, lv){
  return levels[job] != null || (levels[sub] != null && levels[sub] <= lv.sub);
}
// Every spell a word of a set's path can stand for: the spell itself, its tiers ("Cure" -> Cure II...), its
// family ("Utsusemi" -> Utsusemi: Ichi...)
let ACCESS_SPELLS = null;
function accessSpellsOf(word){
  if (!ACCESS_SPELLS) { ACCESS_SPELLS = {};
    for (const name of Object.keys(SPELL_ACCESS)) { const head = name.split(/[ :]/)[0]; (ACCESS_SPELLS[head] = ACCESS_SPELLS[head] || []).push(name); } }
  return (ACCESS_SPELLS[word.split(/[ :]/)[0]] || []).filter(n => n === word || n.startsWith(word + ' ') || n.startsWith(word + ':'));
}
// true / false when the words of the path tell, null when they do not
function accessOfWord(word, job, sub, lv){
  if (ACCESS_PLAIN.has(word) || ACCESS_MODES.test(word)) return null;
  if (JA_ACCESS[word]) return accessJa(JA_ACCESS[word], job, sub, lv);
  if (ACCESS_KINDS[word]) { const rows = Object.entries(JA_ACCESS).filter(([n]) => ACCESS_KINDS[word].test(n)).flatMap(([, r]) => r); return rows.length ? accessJa(rows, job, sub, lv) : null; }
  // a magic skill ("Enhancing Magic"): any spell of it
  const ofSkill = Object.keys(SPELL_SKILL).filter(n => SPELL_SKILL[n] === word);
  if (ofSkill.length) return ofSkill.some(n => accessSpell(SPELL_ACCESS[n], job, sub, lv));
  const spells = accessSpellsOf(word);
  return spells.length ? spells.some(n => accessSpell(SPELL_ACCESS[n], job, sub, lv)) : null;
}
// Can the job shown use this set, with the subjob shown? Kept per job and subjob (asked for every set at each redraw)
let ACCESS_MEMO = {key: null, out: {}};
function setUsable(path, fam){
  if (typeof JA_ACCESS === 'undefined') return true;
  const d = data() || {}, job = S.job, sub = d.sub || '', lv = jaLevels(), key = [S.char, job, sub, lv.main, lv.sub].join('|');
  if (ACCESS_MEMO.key !== key) ACCESS_MEMO = {key, out: {}};
  if (path in ACCESS_MEMO.out) return ACCESS_MEMO.out[path];
  let ok = true;
  if (fam === 'pet') ok = PET_MAIN.includes(job) || PET_SUB.includes(sub);
  else if (fam !== 'ws' && fam !== 'weapons' && fam !== 'idle' && fam !== 'engaged') {
    // the first word that tells decides: the ability or spell the set is for comes before how it is worn
    for (const word of segs(path)) { const got = accessOfWord(word, job, sub, lv); if (got != null) { ok = got; break; } }
  }
  return (ACCESS_MEMO.out[path] = ok);
}
// The cards (a set and its versions) the job cannot use: every version of it out of reach
const cardUsable = card => card.variants.some(v => setUsable(v.set.path, card.fam));
